    let arguments = node.arguments().ok()?;
    let first_arg = arguments.args().into_iter().next()?.ok()?;
    let expression = first_arg.as_any_js_expression()?;
    let value = expression.as_static_value()?;
    Some(value.as_string_constant()?.to_string())
